<script setup lang="ts">
import {computed,onMounted,ref,nextTick} from 'vue';
import KsuEntryForm from './KsuEntryForm.vue';
import KsuSpecialties from './KsuSpecialties.vue';
const tab=ref('receipts');
const props=defineProps<{canEdit:boolean,api:(path:string,method?:string,body?:unknown)=>Promise<any>}>();
const emit=defineEmits<{record:[id:number],receipt:[id:number]}>();
const year=ref(Number(new Intl.DateTimeFormat('en',{year:'numeric',timeZone:'Asia/Almaty'}).format(new Date())));
const report=ref<any>(null),options=ref<any>(null),busy=ref(false),error=ref(''),message=ref(''),detail=ref(false),mapping=ref<any[]>([]),rulesOpen=ref(false),ruleQuery=ref('');
const newRule=ref({code:'',label:'',kind:'',language:'',media:'',version:0});
const filteredRules=computed(()=>mapping.value.filter(r=>(r.code+' '+r.label).toLowerCase().includes(ruleQuery.value.toLowerCase())));
const groups=computed(()=>{const out:{label:string,count:number}[]=[];for(const c of report.value?.columns||[]){const last=out.at(-1);if(last&&last.label===c.group)last.count++;else out.push({label:c.group,count:1});}return out;});
const active=computed(()=>report.value?.rows.filter((r:any)=>r.status!=='cancelled')||[]);
const status=(r:any)=>r.status==='cancelled'?'Отменено · вне итогов':r.status==='incomplete'?'Проверьте исходные данные':'Рассчитано автоматически';
const money=(v:any)=>Number(v||0).toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2});
function date(v:string){return v?v.split('-').reverse().join('.'): '—';}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
async function refresh(){report.value=await props.api('/ksu/report?year='+year.value);}
async function load(){await run(refresh);}
async function saveRule(r:any){await run(async()=>{await props.api('/ksu/rules','PUT',r);mapping.value=(await props.api('/ksu/rules')).items;newRule.value={code:'',label:'',kind:'',language:'',media:'',version:0};await refresh();message.value='Соответствие сохранено. КСУ пересчитана.';});}
async function download(){await run(async()=>{const r=await fetch('/api/ksu/export?year='+report.value.year,{credentials:'same-origin'});if(!r.ok){const d=await r.json();throw Error(d.detail||'Не удалось выгрузить КСУ');}const url=URL.createObjectURL(await r.blob());const a=document.createElement('a');a.href=url;a.download='КСУ-поступления-'+report.value.year+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});}
const editing=ref<any>(null),members=ref<any>(null),membersDialog=ref<HTMLDialogElement|null>(null),memberOffset=ref(0),entryHistory=ref<any[]>([]);
function createEntry(){editing.value={number:report.value.next_number,year:year.value,registered_on:new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Almaty',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),document_on:'',source:'',invoice:'',note:''};}
async function savedEntry(saved:any){const selectedYear=saved.year;editing.value=null;year.value=selectedYear;await run(async()=>{await refresh();message.value='КСУ сохранена. Теперь её можно выбрать в экземплярах каталога.';});}
async function viewMembers(r:any,offset=0){await run(async()=>{members.value=await props.api('/ksu/entries/'+r.id+'/copies?offset='+offset);memberOffset.value=offset;entryHistory.value=[];await nextTick();if(!membersDialog.value?.open)membersDialog.value?.showModal();});}
function openRecord(id:number){membersDialog.value?.close();emit('record',id);}
async function viewHistory(){await run(async()=>{entryHistory.value=await props.api('/ksu/history/'+members.value.entry.id);});}
onMounted(()=>run(async()=>{options.value=await props.api('/ksu/options');mapping.value=(await props.api('/ksu/rules')).items;await refresh();}));
</script>
<template>
<div class="record-tabs ksu-tabs" role="group" aria-label="Отчёты КСУ"><button :class="{active:tab==='receipts'}" :aria-pressed="tab==='receipts'" @click="tab='receipts'">Поступления · первый лист</button><button :class="{active:tab==='specialties'}" :aria-pressed="tab==='specialties'" @click="tab='specialties'">Поступления по специальностям</button></div>
<KsuSpecialties v-if="tab==='specialties'" :api="api" @record="emit('record',$event)" @receipt="emit('receipt',$event)" />
<section v-show="tab==='receipts'" class="ksu-page" :aria-busy="busy">
 <div class="page-heading"><div><div class="eyebrow">УЧЁТ ФОНДА</div><h1>КСУ · Поступления</h1><p>Книга суммарного учёта — первый лист.</p></div><div class="record-actions"><button v-if="canEdit" class="primary" :disabled="busy||!report" @click="createEntry">＋ Создать КСУ</button><button :disabled="busy||!report||!!report.issue_count" @click="download">Скачать Excel</button></div></div>
 <form class="card ksu-toolbar" @submit.prevent="load"><label>Год регистрации<input v-model.number="year" type="number" min="1900" max="9999" required></label><button :disabled="busy">Показать</button><label class="check-label"><input type="checkbox" v-model="detail">Все графы первого листа</label></form>
 <p v-if="error" role="alert" class="inline-error">{{error}}</p><p v-if="message" role="status">{{message}}</p>
 <p class="profile-note">Создайте КСУ с номером и годом, затем выберите её при создании или изменении экземпляра в каталоге. Количество, стоимость, язык, вид литературы и УДК заполняются автоматически. Поступления партиями также продолжают формировать КСУ.</p>
 <p v-if="report?.issue_count" class="pending-note" role="alert">Есть неполные или противоречивые исходные данные. Количество поступивших экземпляров включено полностью, распределение по графам — только по определённым категориям. Выгрузка станет доступна после исправления.</p>
 <p v-if="report?.unpriced_count" role="alert" class="inline-error">Без учётной цены в тенге: {{report.unpriced_count}} экз. Показана только известная сумма, она не является полной стоимостью поступлений.</p>
 <div v-if="report" class="card holdings">
  <div class="ksu-summary"><span><b>{{active.length}}</b> записей КСУ</span><span><b>{{report.totals.titles}}</b> наименований по КСУ</span><span><b>{{report.totals.copies}}</b> экземпляров</span><span><b>{{money(Number(report.totals.on_amount)+Number(report.totals.off_amount))}} ₸</b> {{report.unpriced_count?'известная сумма':'общая сумма'}}</span></div>
  <p class="profile-note">Наименования считаются отдельно в каждой КСУ; это не число уникальных названий всего фонда. Суммы — стоимость книг в тенге, без доставки. Списания не уменьшают исторические поступления.</p>
  <div class="table-wrap ksu-table" tabindex="0" aria-label="Таблица КСУ с горизонтальной прокруткой">
   <table v-if="detail"><thead><tr><th rowspan="2">Дата записи</th><th rowspan="2">№</th><th rowspan="2">Источник поступления</th><th rowspan="2">Дата документа</th><th v-for="g in groups" :key="g.label" :colspan="g.count">{{g.label}}</th><th rowspan="2">Состояние</th></tr><tr><th v-for="c in report.columns" :key="c.key">{{c.label}}</th></tr></thead><tbody><tr v-for="r in report.rows" :key="r.id" :class="{cancelled:r.status==='cancelled'}"><td>{{date(r.registered_on)}}</td><td>{{r.number}}/{{r.year}}</td><td>{{r.source}}</td><td>{{date(r.document_on)}}</td><td v-for="c in report.columns" :key="c.key">{{c.key.endsWith('_amount')?money(r.metrics[c.key]):r.metrics[c.key]}}</td><td>{{status(r)}}<button :disabled="busy" @click="viewMembers(r)">Экземпляры</button><button v-if="canEdit" :disabled="busy" @click="editing={...r}">Изменить КСУ</button><button v-if="r.acquisition_id" :disabled="busy" @click="emit('receipt',r.acquisition_id)">Поступление №{{r.acquisition_id}}</button></td></tr></tbody><tfoot><tr><th colspan="4">Итого (без отменённых)</th><td v-for="c in report.columns" :key="c.key">{{c.key.endsWith('_amount')?money(report.totals[c.key]):report.totals[c.key]}}</td><td></td></tr></tfoot></table>
   <table v-else><thead><tr><th>№ КСУ / дата записи</th><th>Источник / документ</th><th>Наименования</th><th>Экземпляры</th><th>На балансе, ₸</th><th>Не на балансе, ₸</th><th>Состояние</th></tr></thead><tbody><tr v-for="r in report.rows" :key="r.id" :class="{cancelled:r.status==='cancelled'}"><td>{{r.number}}/{{r.year}}<small class="block">{{date(r.registered_on)}}</small></td><td>{{r.source}}<small class="block">{{r.invoice||'Без номера документа'}} · {{date(r.document_on)}}</small></td><td>{{r.metrics.titles}}</td><td>{{r.metrics.copies}}</td><td>{{money(r.metrics.on_amount)}}</td><td>{{money(r.metrics.off_amount)}}</td><td>{{status(r)}}<div class="record-actions"><button :disabled="busy" @click="viewMembers(r)">Экземпляры</button><button v-if="canEdit" :disabled="busy" @click="editing={...r}">Изменить КСУ</button><button v-if="r.acquisition_id" :disabled="busy" @click="emit('receipt',r.acquisition_id)">Поступление №{{r.acquisition_id}}</button></div></td></tr></tbody><tfoot><tr><th colspan="2">Итого</th><td>{{report.totals.titles}}</td><td>{{report.totals.copies}}</td><td>{{money(report.totals.on_amount)}}</td><td>{{money(report.totals.off_amount)}}</td><td></td></tr></tfoot></table>
  </div><p v-if="!report.rows.length" class="empty">За этот год строк КСУ пока нет. Нажмите «Создать КСУ», затем привяжите к ней экземпляры в каталоге.</p>
 </div>
 <section v-if="report?.issue_count" class="card holdings"><h2>Что исправить в исходных данных</h2><template v-for="r in report.rows" :key="r.id"><article v-if="r.status==='incomplete'" class="receipt-card"><h3>КСУ {{r.number}}/{{r.year}} · {{r.source}}</h3><button @click="viewMembers(r)">Открыть экземпляры</button><div v-for="(issue,i) in r.issues" :key="i"><p><button @click="emit('record',issue.record_id)">{{issue.title}} · запись №{{issue.record_id}}</button></p><ul><li v-for="text in issue.messages">{{text}}</li></ul></div></article></template></section>
 <section v-if="canEdit&&options" class="card holdings ksu-candidates"><button :aria-expanded="rulesOpen" @click="rulesOpen=!rulesOpen">{{rulesOpen?'Скрыть':'Открыть'}} соответствия кодов литературы</button><div v-if="rulesOpen"><h2>Соответствия 952$a для всей библиотеки</h2><p>Настраиваются один раз. Категория и язык из кода не должны противоречить карточке. Для справочных изданий, брошюр и АВД выберите принятую в вашей библиотеке категорию.</p><input v-model="ruleQuery" aria-label="Поиск кода литературы" placeholder="Код или расшифровка"><div class="table-wrap"><table><thead><tr><th>Код / расшифровка</th><th>Категория первого листа</th><th>Язык</th><th>АВД</th><th></th></tr></thead><tbody><tr v-for="r in filteredRules" :key="r.code"><td>{{r.code}}<small class="block">{{r.label}}</small></td><td><select v-model="r.kind" :aria-label="'Категория '+r.code"><option value="">Не назначена</option><option v-for="(name,key) in options.kinds" :value="key">{{name}}</option></select></td><td><select v-model="r.language" :aria-label="'Язык '+r.code"><option value="">Из 041$a</option><option v-for="(name,key) in options.languages" :value="key">{{name}}</option></select></td><td><select v-model="r.media" :aria-label="'АВД '+r.code"><option v-for="(name,key) in options.media" :value="key">{{name}}</option></select></td><td><button :disabled="busy" @click="saveRule(r)">Сохранить {{r.code}}</button></td></tr></tbody></table></div><form @submit.prevent="saveRule(newRule)" class="acquisition-grid"><label>Новый код<input v-model="newRule.code" required maxlength="120"></label><label>Расшифровка<input v-model="newRule.label" maxlength="255"></label><label>Категория<select v-model="newRule.kind" required><option value="">Выберите</option><option v-for="(name,key) in options.kinds" :value="key">{{name}}</option></select></label><label>Язык<select v-model="newRule.language"><option value="">Из 041$a</option><option v-for="(name,key) in options.languages" :value="key">{{name}}</option></select></label><label>АВД<select v-model="newRule.media"><option v-for="(name,key) in options.media" :value="key">{{name}}</option></select></label><button :disabled="busy">Добавить соответствие</button></form></div></section>
</section>
<KsuEntryForm v-if="editing" :entry="editing" :api="api" @close="editing=null" @saved="savedEntry" />
<dialog ref="membersDialog" class="modal card acquisition-dialog" aria-labelledby="ksu-members-title">
 <template v-if="members"><h2 id="ksu-members-title">КСУ {{members.entry.label}} · Экземпляры</h2><p>{{members.entry.source}} · {{members.entry.invoice||'Без номера документа'}}</p>
 <p v-if="error" class="inline-error" role="alert">{{error}}</p>
 <div class="table-wrap"><table><thead><tr><th>Книга</th><th>Инв. номер</th><th>Цена</th><th>Дата поступления</th><th>Статус учёта</th></tr></thead><tbody><tr v-for="c in members.items" :key="c.id"><td><button @click="openRecord(c.record_id)">{{c.title||'Открыть книгу'}}</button></td><td>{{c.inventory_number}}</td><td>{{c.unit_price===null?'Не указана':c.unit_price+' '+c.currency}}</td><td>{{date(c.received_on)}}</td><td>{{c.status==='withdrawn'?'Списан · сохранён в истории поступлений':'На учёте'}}</td></tr></tbody></table></div>
 <p v-if="!members.total">Экземпляры ещё не добавлены. Откройте книгу в каталоге, создайте или измените экземпляр и выберите эту КСУ.</p>
 <div class="table-footer"><span>Всего: {{members.total}}</span><button :disabled="busy||memberOffset===0" @click="viewMembers(members.entry,memberOffset-50)">Назад</button><button :disabled="busy||memberOffset+members.items.length>=members.total" @click="viewMembers(members.entry,memberOffset+50)">Далее</button></div>
 <button :disabled="busy" @click="viewHistory">История КСУ</button><ul><li v-for="(h,i) in entryHistory" :key="i">{{h.created_at}} · {{h.reason}}<details><summary>Изменения</summary><pre>{{JSON.stringify({до:h.before,после:h.after},null,2)}}</pre></details></li></ul>
 <div class="modal-actions"><button @click="membersDialog?.close()">Закрыть</button></div></template>
</dialog>
</template>
<style scoped>
.ksu-tabs{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:24px}.ksu-tabs button{transition:none}.ksu-tabs button[aria-pressed="false"]{background:white!important;color:#33465c!important}.ksu-tabs button[aria-pressed="true"]{background:#002341!important;color:white!important;border-color:#002341!important}

.ksu-toolbar{display:flex;gap:20px;align-items:end;padding:20px;margin-bottom:20px;flex-wrap:wrap}.ksu-toolbar label:not(.check-label),.ksu-dialog label{display:flex;flex-direction:column;gap:6px}.ksu-toolbar input[type=number]{max-width:120px}.ksu-summary{display:flex;gap:24px;flex-wrap:wrap}.ksu-summary b{display:block;font-size:23px}.ksu-table{max-height:65vh;overflow:auto}.ksu-table table{border-collapse:separate;border-spacing:0;min-width:100%}.ksu-table th,.ksu-table td,.ksu-classification th,.ksu-classification td{padding:10px;border-bottom:1px solid #dce3ed;min-width:100px;text-align:left}.ksu-table thead th{background:#eef3fa}.ksu-table tfoot{font-weight:bold;background:#eef3fa}.ksu-table .cancelled{color:#788391;background:#f4f4f4}.block{display:block;margin-top:6px}.ksu-candidates{margin-top:20px}.ksu-candidate{display:flex;justify-content:space-between;align-items:center;gap:16px;border-bottom:1px solid #eee;padding:12px 0}.ksu-dialog::backdrop{background:#1e293b88}.ksu-dialog{margin:auto;border:1px solid #dce3ed;width:min(1500px,96vw);max-height:92vh;overflow:auto;padding:24px}.ksu-classification select{max-width:190px;min-width:120px}.ksu-classification td:first-child{min-width:230px}.modal-backdrop{position:fixed;inset:0;z-index:100;background:#1e293b88;display:flex;align-items:center;justify-content:center}.ksu-dialog .modal-actions{position:sticky;bottom:-24px;background:white;padding:16px 0;margin-top:16px}
</style>
